INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','راهنمای جامع و فنی برای مدیریت دقیق آفات و بیماری‌های زعفران با استفاده از سیستم آبیاری قطره‌ای به زبان ساده برای کشاورزان عراق.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
