INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Маводи фарогири ҷамъшуда дар бораи пешгириӣ ва идоракунии офатҳо ва бемориҳои сафроне дар ҳоле ки обёрӣ тавассути қатра истифода карда мешавад. Таъсири мусбати чорбақуни ҳадафмандро дида бароред.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
