INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Умед доред, ки қандақолаҳатонро бо навори тиқ нигоҳ доред? Ин мақола нуктаҳои муҳимро оварда мекунад, ки то обёривии беҳтар ва натиҷаи хушбурро даст меоваред. Бовариҳатонро дар бораи усулҳои муосири нигоҳубаҳи қандол зиёд мекунед.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
