INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима дар муҳимияти масофаи ҷиҳоди (лаччаги) дар корзи хӯшаки чӯлӣ</h2><p>Корзи хӯшаки чӯлӣ ҳамчун яке аз ҳосилҳои ҳассос ба системаи обёрӣ, ба идоракунии дақиқи манбаҳои об ниёз дорад. Дар ин ҳолат, <strong>масофаи ҷиҳоди (лаччаги) дар корзи хӯшаки чӯлӣ</strong> нақшги ҳаётанокиро дар муайян кардани самаранокии системаи обёрӣ дар наққа (капиллярӣ) иҷро мекунад. Муайян кардани масофаи мувофиқ на танҳо ба пӯшиши решаи растанӣ таъсир мерасонад, балки бевосита ба ҳаҷми парҳези истифодаи об ва камшавии маблағҳои ҷорӣ дар моҳвара таъсир мегардонад. Бисёре аз деҳқонҳо бо вуҷуди истифодаи асбобу анборҳои пешрафта, бо сабаби риоя накардани меъёрҳои ҷойгиршавӣ, бо мушкилоти мисли сироят ба бемориҳои хокӣ ё равон нашудани об ноустувор мушаккиф мешаванд. Мақсади ин мақола пешниҳоди роҳнамои умумиву амалиябароянда барои муҳандисони арҷманда ва деҳқонҳо аст, то онҳо бо дониши комил беҳтарин пиктастро барои моҳвараи худ интихоб карда тавонанд.</p><p>Истифодаи ҷиҳоди (лаччаги) бо сабаби анҷомнокиҳо ва қобилияти интиқол дидани диққати зиёдро пайдо кардааст. Аммо барои ҳар як ҳосил андозаҳои махсуси худ дорад. Дар ин ҷо, қатъҳои гуногуни техникиву амалиро бо тафсилот баррасӣ хоҳем кард. <figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-شاهی-استانداردهای-توصیهشده-تصویر-شاخص.webp" alt="فاصله نوار تیپ در کشت شاهی: استانداردهای توصیه‌شده - تصویر 1"/><figcaption>масофаи ҷиҳоди (лаччаги) ҷойгиркунии сатҳ ҳосили хӯшаки чӯлӣ</figcaption></figure></p><h2>Параметрҳои таъсиррасон ба муайян кардани масофаи ҷиҳоди (лаччаги)</h2><h3>Таъсири навъи хок ба сифати дучори об</h3><p>Навъи хок яке аз муҳимтарин тағйирёбандаҳои физикӣ аст, ки бевосита ба вобастагии масофаи тавсияшудаи ҷиҳодҳо (лаччакҳо) таъсир мерасонад. Дар хоки чун (глини) бо сифати дучори паст, об ба сатҳи уфуқӣ бо радиуси маҳдуд пурра мешавад; бинобар ин, масофаи кӯтоҳтар байни ҷиҳодҳо (масалан, 40 то 50 сантиметр) метавонад боиси пӯшиши беҳтари минтақаи реша шавад. Аз дигар ҷонба, дар хоки симишқ (қумӣ), ки сифати дучори баланд дорад, об тезтар дар атроф меравад ва радиуси паҳншавии уфуқии он камтар аст. Дар ин ҳолат, масофаҳои калонтар ё масофаҳои зичтар вобаста ба амиқии решаи хӯшаки чӯлӣ бояд бо эҳтиёт ва тавассути анҷомни санҷишҳои майдона мутобиқ карда шаванд. Диққат накардан ба ин фарқиятҳо метавонад боиси шӯрбуди маҳаллӣ ё камбудии намнокӣ дар минтақаҳои байни ҷиҳодҳо шавад.</p><h3>Нақши зичии корзи ва андозаи растанӣ</h3><p>Хӯшаки чӯлӣ оддӣ бо зичиҳои гуногун кориз мешавад. Дар корзиҳои зич, масофа байни сатҳҳо (Редиф) худро маҳдуд мекунад. Масофаи ҷиҳоди (лаччаги) бояд алоқамандии пурра бо масофаи байнисатҳӣ (Row spacing) дошта бошад. Агар масофа байни сатҳҳо 60 сантиметр бошад, гузоштани ҷиҳоди дар масофаи мисли 40 ё 50 сантиметр метавонад оптималӣ бошад. Ин ҷойгиршавӣ кафолат мекунад, ки намнокии кофӣ барои тармак кардани решаҳои сатҳии хӯшаки чӯлӣ дастрас бошад. Барои шиносоии бештар бо тарзи интихоби миқдори чанг ва зичии мувофиқ дар ҳосилҳои дигари монанд, шумо метавонед мақолаи миқдори чанги лӯбиёи сабз дар гектарро омӯзед, ки принсипҳои монандро дар тақсимоти манбаҳо дорад.</p><p>Илова бар ин, рӯйшадании рӯшани хӯшаки чӯлӣ боиси афзоиши сипарии растанӣ мегардад. Масофаи ҷиҳоди (лаччаги) бояд дар назар гирад, ки оё ҷиҳоди дар зерини сипарӣ ҷойгир мешавад ё дар фазои кушошӣ байни сатҳҳо. Ин масъала ба суръати бухоршавӣ ва бозгашти намнокӣ ба растанӣ таъсир мерасонад. <figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-شاهی-استانداردهای-توصیهشده-کاربرد-عملی.webp" alt="فاصله نوار تیپ در کشت شاهی: استانداردهای توصیه‌شده - تصویر 2"/><figcaption>масофаи ҷиҳоди (лаччаги) ҷойгиркунии сатҳ ҳосили хӯшаки чӯлӣ</figcaption></figure></p><h2>Меъёрҳои тавсияшуда вобаста ба шарту ҳолати моҳвара</h2><h3>Тавсияҳои умумӣ барои хӯшаки чӯлӣ</h3><p>Дар асоси таҳқиқоти майдонавӣ, масофаи бехатар ва оптималӣ барои насби ҷиҳоди (лаччаги) дар корзи хӯшаки чӯлӣ оддӣ дар вобастагии 45 то 60 сантиметр аз сатҳҳо ё аз ҷоҳорои худ мавқеъгирӣ мекунад. Ин вобастагиҳо вобаста ба шартҳои зерин тағйир меёбанд:</p><ul><li><strong>Моҳвараҳо бо хоки сабуқ:</strong> Масофаҳои наздиктар (45-50 сантиметр) барои пешгирии аз дастдани об дар амӣ тавсия дода мешавад.</li><li><strong>Деҳқонҳо бо хок вазнин:</strong> Фосилаҳои васеътар (55-60 сантиметр) бо сабаби паҳншавии беҳтари оби афқӣ имконпазир аст.</li><li><strong>Навъи маҳсулоти шаҳӣ:</strong> Шаҳии гулӣ (Flower) бо шаҳии хӯрока аз ҷиҳати суръати афзоиши реша фарқ дорад; дар шаҳии гулӣ, намоишдиҳии намнокии устувор дар решаҳои сатҳӣ муҳим аст.</li></ul><h3>Муқоиса бо системаҳои дигар маҳсулот</h3><p>Барои фаҳмиши беҳтари нисбати фосила, метавон ба маҳсулоти дигаре масалан миқдори бобу сабзӣ дар гектар, ки бо вуҷуди андозаи хурди рӯёнаҳо, услуби ҷойгиршавии полосаҳо тақрибан монанд аст, нигаред, зеро ҳарду аз рӯянаҳои ҳассос ба намнокии устувор мебошанд. Интихоби фосилаи полосаи тип барои шаҳӣ низ бояд бо машварат бо департаменти иқлими минтақа амалӣ шавад. <figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/فاصله-نوار-تیپ-در-کشت-شاهی-استانداردهای-توصیهشده-جزئیات-فنی.webp" alt="فاصله نوار تیپ در کشت شاهی: استانداردهای توصیه‌شده - تصویر 3"/><figcaption>drip tape spacing row layout crop шاهی</figcaption></figure></p><h2>Нуктаҳои амалӣ дар насб ва нигоҳдорӣ</h2><ol><li><strong>Танзими баландии полоса:</strong> Полосаи тип бояд дақиқ дар сатҳи хок ва зери сатҳҳои хурди سایебанҳои шаҳӣ ё дар ҷои тамоси хок бо сардо насб шавад, то ки аз буғшавии мустақим пешгирӣ карда шавад.</li><li><strong>Лангариҳои идоракунандаи фишор:</strong> Истифодаи лангариҳои фишоркушанда дар оғози ҳар қитъа, ба баргашти оқим дар охири полоса кӯмак мекунад ва аз ҷудошавии номутобиқ пешгирӣ мекунад.</li><li><strong>Шустушӯи мунтазам:</strong> Шаҳӣ бо сабаби истеъмоли баланди об дар фасли гарм, ба ҷамъшавии рехшавии санг ва рег майл дорад. Полосаи тип ба шустушӯи мунтазам дар фосилаҳои кӯтоҳ ниёз дорад.</li><li><strong>Норамонии фосилаҳои амудӣ:</strong> Агар шаҳӣ бо роҳи куҷалӣ эква шавад, кулҳои хок набояд ба полоса фишор оваранд, ки боиси хазандароӣ кардани полоса гардад.</li></ol><p>Барои интихоби дурусти намуди полоса бо истилоҳот ба таъини қубури лӯла, омӯзиши полосаи тиби шудҳард тавсия дода мешавад, то ки сифати истеҳсоли маҳсулот таъмин карда шавад. Инчунин, фаҳмидани фарқияти усулҳои обёрӣ метавонад дар оптимизатсияи бештар кӯмак расонад; барои намуна, муқоиса бо <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%da%af%d8%b1%d9%87%d8%a7%db%8c-%db%8c%d8%a7-%d8%ae%d9%86%d8%af%d9%82/" target="_blank" rel="noopener">Обори чуқур ё канор</a> Нишон медиҳад, ки системаи оғози наварӣ дар шишбарӣ бо сабаби пӯшиши пурраи рӯяг, samъи баландтарро дорад.</p><h2>Ҷавоб ба саволҳои маъмул (FAQ)</h2><h3>1. Оё фосилаи навар оғози барои шишбарӣ бояд бо фосила байни сатҳҳо якхела бошад?</h3><p>Ҳатман на. Фосилаи навар оғозӣ метавонад каме камтар аз фосила байни сатҳҳо бошад, то устувории рӯяг дар минтақаи шишбарӣ кафолат дода шавад. Мақсад ин аст, ки намнокии дар минтақаи рӯяг ҷамъ шуда бошад, на ҳатман дақиқан дар сатҳҳо.</p><h3>2. Агар шишбарӣ гул кунад, оё фосила тағйир мекунад?</h3><p>Бале, шишбарии гулдор бо сабаби давраи тӯли ҳаёти кӯтоҳтар ва ҳассосияти зиёдтар ба гулдонӣ ба устувории баландтари намнокӣ ниёз дорад. Бинобар ин, мо фосилаи навар оғозиро дар мавсими хушкитарро 45 то 50 сантиметр тавсия мебарем.</p><h3>3. Чӣ тавр мо метавонем аз бастани навар оғозӣ дар парҳез шишбарӣ пешгириӣ кунем?</h3><p>Истифодаи филтрҳои мувофиқ, шустушуви мунтазам ва нигоҳубини лӯлаҳои асосӣ пеш аз ҳар як оғоз. Шишбарӣ аз оби навшавандӯби бо дэби кам истифода мекунад; бинобар ин, филтри 120-140 тавсия карда мешавад.</p><h2>Хулоса ва охирбахшӣ</h2><p>Муайян кардани дуруст <strong>Фосилаи навар оғози дар парҳези шишбарӣ</strong> Ин мӯҳандисии соддатар аз он чизест, ки ба назар мерасад. Бо дар назар гирифтани намуди хок, зичии парҳез ва иқлими минтақа, метавон фосилаи беҳтарро дар андозаи 45 то 60 сантиметр танзим кард. Риояи қоидаҳои насб ва нигоҳубини давравӣ, сабаб мегардид, ки ин система на танҳо истеъмоли обро кам кунад, балки боварии сифат ва миқдори маҳсули шишбариро зиёд намояд. Иҷрои дурусти ҷойгиркунии навар оғозӣ, сармоягузории аҳамиятманд аст, ки боварии иқтисодии боғро дар давраи тӯлонӣ кафолат медиҳад. Мо пеш аз ҳар марҳилаи парҳез тавсия мекунем, ки аз як мутахассиси оғозӣ барои боздид ва баррасии тарҳбандӣ истифода бараед.</p>\n<p><strong>Мавзӯҳои марбут:</strong> <a href="https://navar-abyari.ir/%d9%85%d8%b2%d8%a7%db%8c%d8%a7%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d9%82%d8%b7%d8%b1%d9%87-%d8%a7%db%8c/">Фоидаҳои навар оғозӣ</a>, <a href="https://navar-abyari.ir/miqdori-hasili-chaudor-dar-yek-hektar/">miqdori hasili chaudor dar yek hektar</a>, <a href="https://navar-abyari.ir/qahvagi-chora-kkunanda-miqdori-hosilgiiri-dar-hektar-noroi-tiq/">qahvagi chora kkunanda miqdori hosilgiiri dar hektar noroi tiq</a></p>','Фасолаи нӯри Тип дар парҳези Шаҳӣ: Стандартҳои тавсияшуда','Тавсифи беҳтарин масофаҳо байни сафҳо дар корзари шамъ бо истифода аз нӯри тӯбӣ, ҳамроҳ бо тавсияҳои амалӣ барои зиёд кардани самаранокии обёрӣ ва кам кардани хароҷот.','publish','closed','closed','fasoi-nuri-tip-dar-parhez-i-shahi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
