INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_title','Фасолаи нӯри Тип дар парҳези Шаҳӣ: Қоидаҳои расмӣ ва тавсияҳо' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Мутахассисон дар бораи қоидаҳои стандартии фосои нӯри Тип (Row spacing) дар парҳези Шаҳӣ маълумот медиҳанд. Ин мақола ба фермерони тоҷик кӯмак мекунад, то қавати беҳтарин барои ҳосили баландтарин интихоб кунанд.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
